impl Aggregate {
    pub fn extract_id(v: &crate::kernel::Json) -> Result<String, crate::kernel::Refusal> {
        let by_identity = (|| -> Option<String> {
            let c0 = v.dig("bluebook")?.to_id_component().ok()?;
            let c1 = v.dig("name.value")?.to_id_component().ok()?;
            Some([c0, c1].join(":"))
        })();
        let by_id_key = v.get("id").and_then(|j| j.to_id_component().ok());
        let by_reference_key = v.get("aggregate").and_then(|j| j.to_id_component().ok());

        by_identity
            .or(by_id_key)
            .or(by_reference_key)
            .ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Aggregate: no identity found (tried bluebook, name.value, id, aggregate)"
                        .to_string(),
                )
            })
    }
}

