#[derive(Debug, Clone)]
pub struct DeclareArgs {
    pub bluebook: String,
    pub name: AggregateName,
    pub description: Option<Description>,
    pub provenance: Option<LiteralText>,
    pub position: Option<Position>,
}

pub fn dispatch_declare(
    repo: &mut impl crate::kernel::Repository<Aggregate>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: DeclareArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Aggregate> {
    args.name.check_invariants()?;
    if let Some(v) = &args.description {
        v.check_invariants()?;
    }
    if let Some(v) = &args.provenance {
        v.check_invariants()?;
    }
    if let Some(v) = &args.position {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, AGGREGATE_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                let __hydrate_id: String = format!("{}:{}", args.bluebook, args.name.value);
                if __route.aggregate() != __hydrate_id.as_str() {
                    return Err(crate::kernel::Refusal::TypeMismatch(format!(
                        "Declare routes to {:?}, but its identity facts name {:?}",
                        __route.aggregate(),
                        __hydrate_id
                    )));
                }
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Aggregate {
                        bluebook: Some(args.bluebook.clone()),
                        name: Some(args.name.clone()),
                        description: args.description.clone(),
                        provenance: args.provenance.clone(),
                        identified_by: vec![],
                        attributes: vec![],
                        value_objects: vec![],
                        state_field: None,
                        state_start: None,
                        transitions: vec![],
                        marks: vec![],
                        invariants: vec![],
                        preconditions: vec![],
                        projected_fields: vec![],
                        acknowledgements: vec![],
                        position: args.position.clone(),
                    }),
                    state_independent: true,
                }
            }
            None => {
                let __hydrate_id: String = format!("{}:{}", args.bluebook, args.name.value);
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Aggregate {
                        bluebook: Some(args.bluebook.clone()),
                        name: Some(args.name.clone()),
                        description: args.description.clone(),
                        provenance: args.provenance.clone(),
                        identified_by: vec![],
                        attributes: vec![],
                        value_objects: vec![],
                        state_field: None,
                        state_start: None,
                        transitions: vec![],
                        marks: vec![],
                        invariants: vec![],
                        preconditions: vec![],
                        projected_fields: vec![],
                        acknowledgements: vec![],
                        position: args.position.clone(),
                    }),
                    state_independent: true,
                }
            }
        },
        "Declare",
        "Bluebook::Aggregate",
        "Aggregate",
        "bluebook, name.value",
        &with_references,
        &[],
        None,
        |record| {
            record.bluebook = Some(args.bluebook.clone());
            record.name = Some(args.name.clone());
            record.description = args.description.clone();
            record.provenance = args.provenance.clone();
            record.position = args.position.clone();
            Ok(())
        },
        &[],
        &aggregate_invariants(),
        &["RootDeclared"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

