#[derive(Debug, Clone)]
pub struct HoldsArgs {
    pub holds: String,
    pub name: FieldName,
    pub list: ListFlag,
    pub optional: Option<ListFlag>,
    pub pattern: Option<LiteralText>,
    pub default: Option<LiteralText>,
    pub admits: Option<LiteralText>,
    pub relationship: Option<LiteralText>,
}

pub fn dispatch_holds(
    repo: &mut impl crate::kernel::Repository<Aggregate>,
    id: &str,
    args: HoldsArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Aggregate> {
    args.name.check_invariants()?;
    args.list.check_invariants()?;
    if let Some(v) = &args.optional {
        v.check_invariants()?;
    }
    if let Some(v) = &args.pattern {
        v.check_invariants()?;
    }
    if let Some(v) = &args.default {
        v.check_invariants()?;
    }
    if let Some(v) = &args.admits {
        v.check_invariants()?;
    }
    if let Some(v) = &args.relationship {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, AGGREGATE_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Holds",
        "Bluebook::Aggregate",
        "Aggregate",
        "bluebook, name.value",
        &with_references,
        &[],
        None,
        |record| {
            record.attributes.push(Field {
                name: args.name.value.clone(),
                r#type: args.holds.clone(),
                list: args.list.value.clone(),
                default: args.default.clone().map(|v| v.value.clone()),
                optional: args.optional.clone().map(|v| v.value.clone()),
                pattern: args.pattern.clone().map(|v| v.value.clone()),
                admits: args.admits.clone().map(|v| v.value.clone()),
                relationship: args.relationship.clone().map(|v| v.value.clone()),
            });
            Ok(())
        },
        &[],
        &aggregate_invariants(),
        &["PieceOptionDeclared"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

