#[derive(Debug, Clone)]
pub struct ProjectsArgs {
    pub name: FieldName,
    pub reference: FieldName,
    pub remote_field: FieldName,
}

pub fn dispatch_projects(
    repo: &mut impl crate::kernel::Repository<Aggregate>,
    id: &str,
    args: ProjectsArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Aggregate> {
    args.name.check_invariants()?;
    args.reference.check_invariants()?;
    args.remote_field.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, AGGREGATE_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Projects",
        "Bluebook::Aggregate",
        "Aggregate",
        "bluebook, name.value",
        &with_references,
        &[
            crate::kernel::GivenSpec {
                description: "a projected field is named",
                expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(
                    Expr::Lookup("name.value"),
                )))))),
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "a projected field reads through a reference",
                expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(
                    Expr::Lookup("reference.value"),
                )))))),
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "a projected field names a remote field",
                expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(
                    Expr::Lookup("remote_field.value"),
                )))))),
                corrects_event: None,
            },
        ],
        None,
        |record| {
            record.projected_fields.push(ProjectedField {
                name: args.name.value.clone(),
                reference: args.reference.value.clone(),
                remote_field: args.remote_field.value.clone(),
            });
            Ok(())
        },
        &[],
        &aggregate_invariants(),
        &["ProjectedFieldAttached"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

